from pathlib import Path
import subprocess,time,json,hashlib,datetime
import numpy as np
O=Path(__file__).resolve().parent;P=O.parent
names=['FUCHS_RAW_ACCESS_PLAN_v1.json','FUCHS_RAW_ACQUISITION_v1.json','FUCHS_SCHEMA_INTAKE_v1.json','FUCHS_PRIMARY_REVIEW_v1.json','FUCHS_RELATIVE_MOTION_AND_WEAK_INVERSE_v1.md','FUCHS_RELATIVE_MOTION_AND_WEAK_INVERSE_v2.md','FUCHS_WEAK_DEVELOPMENT_PLAN_v1.json','analyze_fuchs_development_v1.py','fuchs_weak_math_v1.py','check_fuchs_weak_v1.py','FUCHS_WEAK_CONTROLS_v1.json','FUCHS_DEVELOPMENT_RESULTS_v1.json','FUCHS_WEAK_RESULTS_v1.md']
