def check(n,b,d=None):checks.append({'name':n,'passed':bool(b),'detail':d})
for kind,script,output in [('math','check_fuchs_weak_v1.py','FUCHS_WEAK_CONTROLS_v1.json'),('development','analyze_fuchs_development_v1.py','FUCHS_DEVELOPMENT_RESULTS_v1.json')]:
 start=datetime.datetime.now(datetime.timezone.utc).isoformat();t=time.monotonic();r=subprocess.run(['/usr/local/bin/python3','-B',str(P/script)],cwd=O,capture_output=True,timeout=120);elapsed=time.monotonic()-t
 (O/(kind.upper()+'_REPRODUCTION_STDOUT_v1.txt')).write_bytes(r.stdout);(O/(kind.upper()+'_REPRODUCTION_STDERR_v1.txt')).write_bytes(r.stderr)
 runs[kind]={'script':script,'started_utc':start,'elapsed_seconds':elapsed,'timeout_seconds':120,'returncode':r.returncode,'stdout_sha256':hashlib.sha256(r.stdout).hexdigest(),'stderr_sha256':hashlib.sha256(r.stderr).hexdigest(),'parsed':json.loads(r.stdout)}
 check(kind+' exit0',r.returncode==0);check(kind+' saved bytes identical',r.stdout==(P/output).read_bytes());check(kind+' saved JSON identical',json.loads(r.stdout)==json.loads((P/output).read_text()));check(kind+' empty stderr',r.stderr==b'')
math=runs['math'].pop('parsed');author=runs['development'].pop('parsed');own=json.loads((O/'INDEPENDENT_RESULTS_v1.json').read_text());d=own['development_case'];case=[c for c in author['cases'] if c['receiver_demod_hypothesis']==2 and c['source_demod_hypothesis']==3 and c['input_model']=='unit_phasor' and c['duration_s']==1200 and c['model']=='exact_second_order_weak'][0]
check('math25 controls',math['passed']==25 and math['failed']==0);check('24case declared grid',len(author['cases'])==24 and len({(c['receiver_demod_hypothesis'],c['source_demod_hypothesis'],c['input_model'],c['duration_s'],c['model']) for c in author['cases']})==24)
check('metadata raw source binding',author['source_sha256']==own['raw_file']['sha256'] and author['source_bytes']==own['raw_file']['bytes'] and author['points_per_stream']==own['streams'][0]['n'] and author['duration_s']==own['streams'][0]['duration_s'] and author['carrier_from_record_Hz']==own['streams'][7]['first_value'])
check('scope labels',author['development_only'] and not author['empirical_validation'] and not author['force_or_scalar_parameter_estimate'] and not author['reserved_raw_files_opened'])
check('window count and indices',len(case['rows'])==d['n_windows']==17 and all(r['lo']==v['first_index'] and r['hi']==v['last_index_exclusive'] for r,v in zip(case['rows'],d['windows'])))
tfirst=own['streams'][0]['t0'];timeerr=max(max(abs(r['t0']-(v['actual_start']-tfirst)),abs(r['t1']-(v['actual_end']-tfirst))) for r,v in zip(case['rows'],d['windows']));check('window time-origin correspondence',timeerr<1e-10,timeerr)
comp={}
for which,parentwhich in [('all_windows','fit_all'),('chronological','chronological_development_check')]:
 a=case[parentwhich];b=d['results']['trapezoid'][which]
 fields={'parameters':'coefficients','raw_singular_values':'raw_singular_values','normalized_singular_values':'normalized_singular_values','observed':'R','predicted':'predictions','residual':'complex_residuals'}
 err={k:float(np.max(np.abs(np.array(a[k])-np.array(b[v])))) for k,v in fields.items()}
 check(which+' features fit correspondence',max(err.values())<1e-10,err);check(which+' train and rank',a['train_windows']==b['train_windows'] and a['real_rank']==b['rank']==4)
 comp[which]=err
fm=np.array([row['moments'] for row in case['rows']]);fo=np.array(d['results']['trapezoid']['features']);feature_error=float(np.max(np.abs(fm-fo)));check('all68 weak complex features',feature_error<1e-12,feature_error)
quad_delta={k:np.subtract(d['results']['piecewise_linear_Gauss4'][k]['coefficients'],d['results']['trapezoid'][k]['coefficients']).tolist() for k in ['all_windows','chronological']}
check('source unchanged',before==hashes());actualtail=own['streams'][0]['t1']-d['windows'][-1]['actual_end'];check('actual tail correspondence',abs(actualtail-case['unwindowed_tail_s'])<1e-10)
result={'scope':'Narrow post-exposure source/reproduction correspondence. Independent raw parser covers all streams; independently rebuilt real-data regression covers one declared case only. Full24cases reproduced but not independently reimplemented.','source_before':before,'source_after':hashes(),'runs':runs,'checks':checks,'passed':sum(c['passed'] for c in checks),'failed':sum(not c['passed'] for c in checks),'one_case_feature_component_max_error':feature_error,'one_case_fit_comparison':comp,'quadrature_parameter_deltas':quad_delta,'tail_seconds':{'nominal_omitted':d['omitted_final_nominal_length'],'since_last_used_sample':actualtail},'independent_trapezoid_parameters':d['results']['trapezoid']['all_windows']['coefficients'],'author_same_case_parameters':case['fit_all']['parameters'],'independent_case_relative_residual':case['fit_all']['train_residual_rms']/case['fit_all']['train_R_rms'],'late_development_relative_residual':case['chronological_development_check']['validation_residual_rms']/case['chronological_development_check']['validation_R_rms'],'prior_failures_preserved':'Author schema receipt retains NumPy-int64 output serialization failure; primary receipt retains PDF parser warning; no independent scientific run failed. First full math-output display was truncated by tool display budget, original full bytes and replay retained.','v2_scope_confirmation':'Only f=0 qualification for eq4 and consistency-vs-uniqueness clarification were checked via exact v1-v2 diff; complex-probe extension not opened.'}
(O/'AUTHOR_COMPARISON_v1.json').write_text(json.dumps(result,indent=2)+'\n');print(json.dumps({k:v for k,v in result.items() if k not in ['source_before','source_after','checks']},indent=2));assert result['failed']==0
